// Field guide pages and the hub (generated by scripts/build-field-guides.mjs).
// Adds the same prose enhancement the writeups get (heading anchors, copy-able
// code blocks), a filter over the guide's entries, and marks the section being
// read in the jump bar. Without scripts the page is the whole guide with the
// jump links, and the filter box stays hidden.
import { enhanceMarkdownBody } from "../js/markdown.js?v=276fa973-lean";
import { initCommandPalette } from "../js/command-palette.js?v=search2";
import { initSiteHeader } from "../js/site-header.js?v=276fa973-header";
import { initTheme } from "../js/theme.js?v=276fa973";

// Each ### is an entry inside its ## group (wrapped at build time). An entry
// matches when every word of the filter appears in it or in its group's title,
// so "credential" keeps that whole section and "lsass dump" one entry.
const initFilter = () => {
  const row = document.querySelector("[data-guide-filter-row]");
  const input = document.querySelector("[data-guide-filter]");
  const count = document.querySelector("[data-guide-count]");
  const empty = document.querySelector("[data-guide-empty]");
  const intro = document.querySelector("[data-guide-intro]");
  const entries = [...document.querySelectorAll("[data-guide-entry]")].map((entry) => {
    const group = entry.closest("[data-guide-group]");
    const title = group?.querySelector("h2")?.textContent || "";
    return { entry, group, text: `${title} ${entry.textContent}`.toLowerCase() };
  });
  const groups = [...document.querySelectorAll("[data-guide-group]")];
  const jumps = new Map([...document.querySelectorAll(".guide-jump a")].map((link) => [link.hash.slice(1), link]));
  if (!row || !input || !entries.length) return;
  row.hidden = false;

  const apply = () => {
    const words = input.value.toLowerCase().split(/\s+/).filter(Boolean);
    let shown = 0;
    for (const item of entries) {
      item.entry.hidden = !words.every((word) => item.text.includes(word));
      if (!item.entry.hidden) shown += 1;
    }
    for (const group of groups) {
      group.hidden = ![...group.querySelectorAll("[data-guide-entry]")].some((entry) => !entry.hidden);
      jumps.get(group.querySelector("h2")?.id)?.classList.toggle("is-empty", group.hidden);
    }
    count.textContent = words.length ? `${shown} of ${entries.length}` : "";
    empty.hidden = !words.length || shown > 0;
    if (intro) intro.hidden = words.length > 0;
    // keep the filter in the address so a filtered view can be shared
    const url = new URL(location.href);
    if (words.length) url.searchParams.set("q", input.value.trim());
    else url.searchParams.delete("q");
    history.replaceState(history.state, "", url);
  };

  input.value = new URLSearchParams(location.search).get("q") || "";
  if (input.value) apply();
  input.addEventListener("input", apply);
  input.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && input.value) {
      event.preventDefault();
      input.value = "";
      apply();
    }
  });
  document.querySelector("[data-guide-clear]")?.addEventListener("click", () => {
    input.value = "";
    apply();
    input.focus();
  });
  // "/" jumps to the filter, as in most docs sites, unless you're typing
  document.addEventListener("keydown", (event) => {
    if (event.key !== "/" || event.ctrlKey || event.metaKey || event.altKey) return;
    if (event.target.closest?.("input, textarea, select, [contenteditable='true']")) return;
    event.preventDefault();
    input.focus();
    input.select();
  });
};

// The current section is the last visible heading that has passed under the
// sticky bar. Worked out on scroll (once a frame), so fast scrolling and
// jump-link clicks can't skip a section.
const trackSections = () => {
  const bar = document.querySelector(".guide-jump");
  const toolbar = document.querySelector(".guide-toolbar");
  const sections = [...(bar?.querySelectorAll("a") || [])]
    .map((link) => ({ link, heading: document.getElementById(link.hash.slice(1)) }))
    .filter((section) => section.heading);
  if (!sections.length) return;
  let active = null;
  let queued = false;
  const update = () => {
    queued = false;
    const line = (toolbar?.getBoundingClientRect().bottom || 0) + 24;
    const passed = sections.filter((s) => s.heading.offsetParent && s.heading.getBoundingClientRect().top <= line);
    const current = (passed[passed.length - 1] || sections.find((s) => s.heading.offsetParent))?.link || null;
    if (current === active) return;
    active?.classList.remove("is-active");
    active = current;
    active?.classList.add("is-active");
    // keep the marked link in view in the bar without moving the page
    if (active) bar.scrollLeft = active.offsetLeft - bar.clientWidth / 3;
  };
  const queue = () => {
    if (!queued) { queued = true; requestAnimationFrame(update); }
  };
  addEventListener("scroll", queue, { passive: true });
  addEventListener("resize", queue);
  document.querySelector("[data-guide-filter]")?.addEventListener("input", queue);
  update();
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  const body = document.querySelector(".markdown-body");
  if (body) {
    enhanceMarkdownBody(body);
    initFilter();
    trackSections();
  }
});
